1	import { Anchor, Container, Group } from '@mantine/core';
2	import { notFound } from 'next/navigation';
3	
4	import { setDrinkers } from '@/actions/setDrinkers';
5	import { AutoRefresh } from '@/components/AutoRefresh/AutoRefresh';
6	import { DrinkersForm } from '@/components/DrinkersForm/DrinkersForm';
7	import { formatDate } from '@/lib/dates';
8	import gameDayService from '@/services/GameDay';
9	import outcomeService from '@/services/Outcome';
10	import { FootyChannel } from '@/types/FootyChannel';
11	
12	interface PageProps {
13	    params: Promise<{
14	        gameDayId: string,
15	    }>,
16	}
17	
18	export const metadata = { title: 'Drinkers' };
19	
20	const DrinkersPage = async (props: PageProps) => {
21	    const { gameDayId } = await props.params;
22	    const gameId = Number.parseInt(gameDayId, 10);
23	
24	    if (Number.isNaN(gameId) || gameId < 1) return notFound();
25	
26	    const gameDay = await gameDayService.get(gameId);
27	    if (!gameDay) return notFound();
28	
29	    const [players, previousGame, nextGame] = await Promise.all([
30	        outcomeService.getAdminByGameDay(gameId),
31	        gameDayService.getPrevious(gameId),
32	        gameDayService.getNext(gameId),
33	    ]);
34	
35	    return (
36	        <Container size="lg" py="lg">
37	            <AutoRefresh channels={FootyChannel.Games} />
38	            <Group justify="space-between" mb="md">
39	                {
40	                    previousGame ?
41	                        <Anchor href={`/footy/admin/drinkers/${previousGame.id}`}>Previous</Anchor> :
42	                        <span />
43	                }
44	                {
45	                    nextGame ?
46	                        <Anchor href={`/footy/admin/drinkers/${nextGame.id}`}>Next</Anchor> :
47	                        <span />
48	                }
49	            </Group>
50	            <DrinkersForm
51	                gameId={gameDay.id}
52	                gameDate={formatDate(gameDay.date)}
53	                players={players}
54	                setDrinkers={setDrinkers}
55	            />
56	        </Container>
57	    );
58	};
59	
60	export default DrinkersPage;
61

1	'use client';
2	
3	import {
4	    Anchor,
5	    Box,
6	    Button,
7	    Checkbox,
8	    Group,
9	    Image,
10	    Stack,
11	    Table,
12	    TableTbody,
13	    TableTd,
14	    TableTh,
15	    TableThead,
16	    TableTr,
17	    Text,
18	    TextInput,
19	    Title,
20	} from '@mantine/core';
21	import { notifications } from '@mantine/notifications';
22	import { IconAlertTriangle, IconCheck } from '@tabler/icons-react';
23	import { useRouter } from 'next/navigation';
24	import { useMemo, useState } from 'react';
25	
26	import { config } from '@/lib/config';
27	import type { SetDrinkersInput, SetDrinkersProxy } from '@/types/actions/SetDrinkers';
28	import type { OutcomePlayerType } from '@/types/OutcomePlayerType';
29	
30	interface DrinkersFormProps {
31	    gameId: number;
32	    gameDate: string;
33	    players: OutcomePlayerType[];
34	    setDrinkers: SetDrinkersProxy;
35	}
36	
37	export const DrinkersForm = ({
38	    gameId,
39	    gameDate,
40	    players,
41	    setDrinkers,
42	}: DrinkersFormProps) => {
43	    const router = useRouter();
44	    const [rows, setRows] = useState<OutcomePlayerType[]>(() => sortRows(players));
45	    const [selectedIds, setSelectedIds] = useState<number[]>(() => toSelectedIds(players));
46	    const [savedSelectedIds, setSavedSelectedIds] = useState<number[]>(() => toSelectedIds(players));
47	    const [filter, setFilter] = useState('');
48	    const [isSaving, setIsSaving] = useState(false);
49	    const [prevPlayers, setPrevPlayers] = useState(players);
50	
51	    if (prevPlayers !== players) {
52	        setPrevPlayers(players);
53	        setRows(sortRows(players));
54	        const selected = toSelectedIds(players);
55	        setSelectedIds(selected);
56	        setSavedSelectedIds(selected);
57	    }
58	
59	    const selectedIdSet = useMemo(() => new Set(selectedIds), [selectedIds]);
60	
61	    const visibleRows = useMemo(() => {
62	        const searchTerm = filter.trim().toLowerCase();
63	        if (!searchTerm) return rows;
64	
65	        return rows.filter((row) => normaliseName(row).toLowerCase().includes(searchTerm));
66	    }, [rows, filter]);
67	
68	    const allVisibleSelected =
69	        visibleRows.length > 0 &&
70	        visibleRows.every((row) => selectedIdSet.has(row.playerId));
71	
72	    const someVisibleSelected =
73	        visibleRows.some((row) => selectedIdSet.has(row.playerId)) && !allVisibleSelected;
74	
75	    const hasChanges = !isSameSelection(selectedIds, savedSelectedIds);
76	
77	    const togglePlayer = (playerId: number, checked: boolean) => {
78	        setSelectedIds((current) => {
79	            if (checked) {
80	                /* v8 ignore next -- defensive guard against duplicate adds; normal checkbox behaviour never fires checked=true when already selected */
81	                return current.includes(playerId) ? current : [...current, playerId];
82	            }
83	
84	            return current.filter((id) => id !== playerId);
85	        });
86	    };
87	
88	    const toggleVisible = (checked: boolean) => {
89	        const visibleIds = visibleRows.map((row) => row.playerId);
90	        const visibleIdSet = new Set(visibleIds);
91	
92	        setSelectedIds((current) => {
93	            if (checked) {
94	                return Array.from(new Set([...current, ...visibleIds]));
95	            }
96	
97	            return current.filter((id) => !visibleIdSet.has(id));
98	        });
99	    };
100	
101	    const handleSave = async () => {
102	        const payload: SetDrinkersInput = {
103	            gameDayId: gameId,
104	            players: rows.map((row) => ({
105	                playerId: row.playerId,
106	                drinker: selectedIdSet.has(row.playerId),
107	            })),
108	        };
109	
110	        const notificationId = 'drinkers-save';
111	        notifications.show({
112	            id: notificationId,
113	            loading: true,
114	            title: 'Saving drinkers',
115	            message: 'Updating pub attendance...',
116	            autoClose: false,
117	            withCloseButton: false,
118	        });
119	
120	        setIsSaving(true);
121	        try {
122	            const result = await setDrinkers(payload);
123	
124	            setRows((current) => current.map((row) => {
125	                if (!selectedIdSet.has(row.playerId)) {
126	                    return { ...row, pub: null };
127	                }
128	
129	                return { ...row, pub: row.team ? 1 : 2 };
130	            }));
131	            setSavedSelectedIds(selectedIds);
132	
133	            notifications.update({
134	                id: notificationId,
135	                color: 'teal',
136	                title: 'Drinkers updated',
137	                message: `${result.drinkers} players marked for pub attendance.`,
138	                icon: <IconCheck size={config.notificationIconSize} />,
139	                loading: false,
140	                autoClose: config.notificationAutoClose,
141	            });
142	
143	            router.refresh();
144	        } catch (error) {
145	            const message = error instanceof Error ? error.message : 'Failed to update drinkers';
146	            notifications.update({
147	                id: notificationId,
148	                color: 'red',
149	                title: 'Error',
150	                message,
151	                icon: <IconAlertTriangle size={config.notificationIconSize} />,
152	                loading: false,
153	                autoClose: false,
154	                withCloseButton: true,
155	            });
156	        } finally {
157	            setIsSaving(false);
158	        }
159	    };
160	
161	    return (
162	        <Stack gap="md">
163	            <Stack gap={4}>
164	                <Title order={2}>Game {gameId} Drinkers</Title>
165	                <Text c="dimmed">{gameDate}</Text>
166	                <Text c="dimmed">Selected: {selectedIds.length}</Text>
167	            </Stack>
168	
169	            <TextInput
170	                placeholder="Search players"
171	                value={filter}
172	                onChange={(event) => setFilter(event.currentTarget.value)}
173	            />
174	
175	            {rows.length > 0 ? (
176	                <>
177	                    <Checkbox
178	                        label="Select all visible players"
179	                        checked={allVisibleSelected}
180	                        indeterminate={someVisibleSelected}
181	                        onChange={(event) => toggleVisible(event.currentTarget.checked)}
182	                    />
183	
184	                    <Table withTableBorder>
185	                        <TableThead>
186	                            <TableTr>
187	                                <TableTh>Player</TableTh>
188	                                <TableTh>Team</TableTh>
189	                                <TableTh>Response</TableTh>
190	                                <TableTh>Drank</TableTh>
191	                            </TableTr>
192	                        </TableThead>
193	                        <TableTbody>
194	                            {visibleRows.map((row) => {
195	                                const playerName = normaliseName(row);
196	                                return (
197	                                    <TableTr key={row.playerId}>
198	                                        <TableTd>
199	                                            <Group wrap="nowrap" gap="sm">
200	                                                <Anchor href={`/footy/player/${row.playerId}`}>
201	                                                    <Image
202	                                                        w={40}
203	                                                        h={40}
204	                                                        radius="xl"
205	                                                        src={`/api/footy/player/${row.playerId}/mugshot`}
206	                                                        alt={playerName}
207	                                                    />
208	                                                </Anchor>
209	                                                <Anchor href={`/footy/player/${row.playerId}`}>
210	                                                    {playerName}
211	                                                </Anchor>
212	                                            </Group>
213	                                        </TableTd>
214	                                        <TableTd>{row.team ?? '-'}</TableTd>
215	                                        <TableTd>{row.response ?? '-'}</TableTd>
216	                                        <TableTd>
217	                                            <Checkbox
218	                                                aria-label={`Pub ${playerName}`}
219	                                                checked={selectedIdSet.has(row.playerId)}
220	                                                onChange={(event) => togglePlayer(
221	                                                    row.playerId,
222	                                                    event.currentTarget.checked,
223	                                                )}
224	                                            />
225	                                        </TableTd>
226	                                    </TableTr>
227	                                );
228	                            })}
229	                        </TableTbody>
230	                    </Table>
231	
232	                    <Box>
233	                        <Button
234	                            type="button"
235	                            onClick={handleSave}
236	                            loading={isSaving}
237	                            disabled={!hasChanges}
238	                        >
239	                            Save drinkers
240	                        </Button>
241	                    </Box>
242	                </>
243	            ) : (
244	                <Text>No active players found</Text>
245	            )}
246	        </Stack>
247	    );
248	};
249	
250	const normaliseName = (row: OutcomePlayerType) => row.player.name ?? `Player ${row.playerId}`;
251	
252	const sortRows = (rows: OutcomePlayerType[]) => [...rows].sort((a, b) => {
253	    const teamBucketDiff = (a.team ? 0 : 1) - (b.team ? 0 : 1);
254	    if (teamBucketDiff !== 0) return teamBucketDiff;
255	    return normaliseName(a).localeCompare(normaliseName(b));
256	});
257	
258	const toSelectedIds = (rows: OutcomePlayerType[]) => rows
259	    .filter((row) => (row.pub ?? 0) > 0)
260	    .map((row) => row.playerId);
261	
262	const isSameSelection = (left: number[], right: number[]) => {
263	    if (left.length !== right.length) return false;
264	    const rightSet = new Set(right);
265	    return left.every((id) => rightSet.has(id));
266	};
