1	import { normalizeEmail } from '@/lib/email/normalizeEmail';
2	import { PlayerDataType } from '@/types';
3	
4	export type SortKey = 'id' | 'name' | 'joined' | 'finished' | 'auth';
5	export type SortDirection = 'asc' | 'desc';
6	
7	/**
8	 * Compares nullable numeric values with consistent null ordering.
9	 *
10	 * @param a - The left-hand numeric value.
11	 * @param b - The right-hand numeric value.
12	 * @param direction - Sort direction (`asc` or `desc`).
13	 * @returns A comparison value suitable for Array.sort.
14	 */
15	export function compareNullableNumber(
16	    a: number | null | undefined,
17	    b: number | null | undefined,
18	    direction: SortDirection,
19	) {
20	    if (a == null && b == null) return 0;
21	    if (a == null) return 1;
22	    if (b == null) return -1;
23	    return direction === 'asc' ? a - b : b - a;
24	}
25	
26	/**
27	 * Compares nullable string values with locale-aware ordering.
28	 *
29	 * @param a - The left-hand string value.
30	 * @param b - The right-hand string value.
31	 * @param direction - Sort direction (`asc` or `desc`).
32	 * @returns A comparison value suitable for Array.sort.
33	 */
34	export function compareNullableString(
35	    a: string | null | undefined,
36	    b: string | null | undefined,
37	    direction: SortDirection,
38	) {
39	    if (a == null && b == null) return 0;
40	    if (a == null) return 1;
41	    if (b == null) return -1;
42	    const result = a.localeCompare(b);
43	    return direction === 'asc' ? result : -result;
44	}
45	
46	/**
47	 * Determines whether a player has a Better Auth user account.
48	 *
49	 * @param player - The player to check.
50	 * @param userEmailSet - Known Better Auth user emails (lowercased).
51	 * @returns True when the player's accountEmail exists in Better Auth.
52	 */
53	export function isOnboarded(player: PlayerDataType, userEmailSet: Set<string>) {
54	    const email = normalizeEmail(player.accountEmail);
55	    return email.length > 0 && userEmailSet.has(email);
56	}
57	
58	/**
59	 * Applies the current sort key to two players.
60	 *
61	 * @param a - The left-hand player.
62	 * @param b - The right-hand player.
63	 * @param key - The player field to compare.
64	 * @param direction - Sort direction (`asc` or `desc`).
65	 * @param userEmailSet - Known Better Auth user emails (lowercased).
66	 * @returns A comparison value suitable for Array.sort.
67	 */
68	export function comparePlayers(
69	    a: PlayerDataType,
70	    b: PlayerDataType,
71	    key: SortKey,
72	    direction: SortDirection,
73	    userEmailSet: Set<string>,
74	) {
75	    switch (key) {
76	        case 'id':
77	            return compareNullableNumber(a.id, b.id, direction);
78	        case 'name':
79	            return compareNullableString(a.name, b.name, direction);
80	        case 'joined':
81	            return compareNullableNumber(
82	                a.joined ? new Date(a.joined).getTime() : null,
83	                b.joined ? new Date(b.joined).getTime() : null,
84	                direction,
85	            );
86	        case 'finished':
87	            return compareNullableNumber(
88	                a.finished ? new Date(a.finished).getTime() : null,
89	                b.finished ? new Date(b.finished).getTime() : null,
90	                direction,
91	            );
92	        case 'auth':
93	            return compareNullableNumber(
94	                isOnboarded(a, userEmailSet) ? 1 : 0,
95	                isOnboarded(b, userEmailSet) ? 1 : 0,
96	                direction,
97	            );
98	        default:
99	            return 0;
100	    }
101	}
102	
103	/**
104	 * Chooses the best email for a player, preferring accountEmail then verified extras.
105	 *
106	 * @param player - The player to derive the preferred email from.
107	 * @returns The preferred email or an empty string if none is available.
108	 */
109	export function getPreferredEmail(player: PlayerDataType) {
110	    if (player.accountEmail) {
111	        return player.accountEmail;
112	    }
113	    if (!player.extraEmails.length) return '';
114	    const verifiedEmail = player.extraEmails.find((playerEmail) => playerEmail.verified);
115	    return (verifiedEmail ?? player.extraEmails[0])?.email ?? '';
116	}
