118	/**
119	 * Chooses the display label for impersonation status notifications.
120	 *
121	 * @param player - The player being impersonated.
122	 * @returns The player name, account email, or a generic fallback label.
123	 */
124	export function getImpersonationLabel(player: PlayerDataType) {
125	    return player.name ?? player.accountEmail ?? 'player';
126	}
