360	type SortKey = 'name' | 'responseTime' | 'gamesPlayed';
361	type SortDirection = 'asc' | 'desc';
362	
363	const compareNullableNumber = (
364	    a: number | null | undefined,
365	    b: number | null | undefined,
366	    direction: SortDirection,
367	) => {
368	    if (a == null && b == null) return 0;
369	    if (a == null) return 1;
370	    if (b == null) return -1;
371	    return direction === 'asc' ? a - b : b - a;
372	};
373	
374	const compareNullableString = (
375	    a: string | null | undefined,
376	    b: string | null | undefined,
377	    direction: SortDirection,
378	) => {
379	    if (a == null && b == null) return 0;
380	    if (a == null) return 1;
381	    if (b == null) return -1;
382	    const result = a.localeCompare(b);
383	    return direction === 'asc' ? result : -result;
384	};
385	
386	const formatResponseInterval = (seconds: number | null | undefined) => {
387	    if (seconds == null) return '-';
388	    if (seconds < 60) return `${seconds}s`;
389	
390	    const minutes = Math.floor(seconds / 60);
391	    if (minutes < 60) return `${minutes}m`;
392	
393	    const hours = Math.floor(minutes / 60);
394	    const remainingMinutes = minutes % 60;
395	    if (hours < 24) {
396	        return remainingMinutes ? `${hours}h ${remainingMinutes}m` : `${hours}h`;
397	    }
398	
399	    const days = Math.floor(hours / 24);
400	    const remainingHours = hours % 24;
401	    return remainingHours ? `${days}d ${remainingHours}h` : `${days}d`;
402	};
403	
404	const getPlayerName = (row: PickerPlayerType) => row.player.name ?? `Player ${row.playerId}`;
405	
406	const buildDefaultSelection = (rows: PickerPlayerType[], maxSelected = 12) => {
407	    if (!rows.length) return [];
408	    const sorted = [...rows].sort((a, b) => {
409	        const responseCompare = compareNullableNumber(a.responseInterval, b.responseInterval, 'asc');
410	        if (responseCompare !== 0) return responseCompare;
411	        const nameCompare = compareNullableString(a.player.name, b.player.name, 'asc');
412	        if (nameCompare !== 0) return nameCompare;
413	        return a.playerId - b.playerId;
414	    });
415	    return sorted.slice(0, maxSelected).map((row) => row.playerId);
416	};
